<?php
require '../includes/functions.php';$u=require_role('citizen');verify_csrf();$pdo=db();$errors=[];$depts=$pdo->query('SELECT id,name FROM departments WHERE is_active=1 ORDER BY name')->fetchAll();$cats=$pdo->query('SELECT id,department_id,name FROM categories WHERE is_active=1 ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST') { $department=(int)($_POST['department_id']??0);$category=(int)($_POST['category_id']??0);$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$location=trim($_POST['location']??'');$q=$pdo->prepare('SELECT id FROM categories WHERE id=? AND department_id=? AND is_active=1');$q->execute([$category,$department]);if(!$q->fetch())$errors[]='Choose a valid category for the selected department.';if(mb_strlen($title)<5||mb_strlen($title)>180)$errors[]='Title must be 5 to 180 characters.';if(mb_strlen($description)<20)$errors[]='Please provide at least 20 characters of detail.';if(strlen($location)<2||strlen($location)>255)$errors[]='Enter the location (up to 255 characters).';
 $file=$_FILES['attachment']??null;$stored=null;if($file&&$file['error']!==UPLOAD_ERR_NO_FILE){if($file['error']!==UPLOAD_ERR_OK||$file['size']>MAX_UPLOAD_BYTES)$errors[]='File must be no larger than 5 MB.';else{$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf'];if(!isset($allowed[$mime]))$errors[]='Only JPEG, PNG, and PDF files are accepted.';else{$stored=bin2hex(random_bytes(20)).'.'.$allowed[$mime];}}}
 if(!$errors){if(!is_dir(UPLOAD_DIR))mkdir(UPLOAD_DIR,0750,true);$pdo->beginTransaction();try{$tracking='GRV-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(4)));$q=$pdo->prepare("INSERT INTO grievances(tracking_number,citizen_id,department_id,category_id,title,description,location) VALUES(?,?,?,?,?,?,?)");$q->execute([$tracking,$u['id'],$department,$category,$title,$description,$location]);$id=(int)$pdo->lastInsertId();record_history($pdo,$id,null,'Submitted',$u['id'],'Grievance submitted');if($stored){if(!move_uploaded_file($file['tmp_name'],UPLOAD_DIR.'/'.$stored))throw new RuntimeException('Upload failed');$q=$pdo->prepare('INSERT INTO grievance_attachments(grievance_id,original_name,stored_name,mime_type,file_size) VALUES(?,?,?,?,?)');$q->execute([$id,basename($file['name']),$stored,$mime,$file['size']]);}$pdo->commit();flash('Grievance submitted. Tracking number: '.$tracking);redirect('citizen/view.php?id='.$id);}catch(Throwable $ex){$pdo->rollBack();if($stored&&is_file(UPLOAD_DIR.'/'.$stored))unlink(UPLOAD_DIR.'/'.$stored);$errors[]='Submission could not be saved. Please try again.';}}
}
$pageTitle='Submit grievance';require '../includes/header.php';?><section class="panel form-narrow"><h1>Submit a grievance</h1><?php foreach($errors as $er):?><p class="error"><?=e($er)?></p><?php endforeach?><form method="post" enctype="multipart/form-data"><?=csrf_field()?><label for="department">Department</label><select id="department" name="department_id" required><option value="">Select department</option><?php foreach($depts as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach?></select><label for="category">Category</label><select id="category" name="category_id" required><option value="">Select category</option><?php foreach($cats as $c):?><option data-dept="<?=$c['department_id']?>" value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach?></select><label for="title">Title</label><input id="title" name="title" maxlength="180" required value="<?=e($_POST['title']??'')?>"><label for="description">Describe the concern</label><textarea id="description" name="description" minlength="20" required><?=e($_POST['description']??'')?></textarea><label for="location">Location of issue</label><input id="location" name="location" maxlength="255" required><label for="attachment">Evidence (JPEG, PNG or PDF; max 5 MB)</label><input id="attachment" type="file" name="attachment" accept="image/jpeg,image/png,application/pdf"><button>Submit grievance</button></form></section><script>document.getElementById('department').addEventListener('change',e=>{for(const o of document.querySelectorAll('#category option[data-dept]'))o.hidden=o.dataset.dept!==e.target.value;document.getElementById('category').value='';});</script><?php require '../includes/footer.php';?>
